class Ticket { private static int next=5000; private final int id; Ticket(){id=++next;} int getId(){return id;} }
class Facility { private static int totalTickets; private final String gate; Facility(String gate){this.gate=gate;} Ticket issue(){totalTickets++;return new Ticket();} static int getTotalTickets(){return totalTickets;} String getGate(){return gate;} }
public class Task05 { public static void main(String[] args){Facility north=new Facility("North"),south=new Facility("South"); Ticket a=north.issue(),b=south.issue();System.out.println(north.getGate()+" ticket="+a.getId());System.out.println(south.getGate()+" ticket="+b.getId());System.out.println("Tickets issued across facilities="+Facility.getTotalTickets());System.out.println("After exit, an unreferenced ticket is eligible for garbage collection");}}
